<?php
require_once __DIR__ . '/_layout.php';requirePermission('reservations.manage');$agencyIds=currentAgencyIds();if(!$agencyIds)$agencyIds=[0];$agencyId=(int)($_GET['agency_id']??$_POST['agency_id']??$agencyIds[0]);requireAgencyAccess($agencyId);
if(requestMethod()==='POST'){requireCsrfPost();try{$id=createReservation($_POST);flash('success',t('message.reservation_created',['id'=>$id]));safeRedirect('reservation_detail.php?id='.$id);}catch(AuthorizationException$e){http_response_code(403);exit(t('validation.not_authorized'));}catch(InvalidArgumentException|DomainException$e){flash('danger',$e->getMessage());}catch(Throwable$e){reportDatabaseError($e,'Reservation creation failed');flash('danger',t('message.reservation_failed'));}}
$agencies=dbFetchAll("SELECT id,name FROM agencies WHERE archived_at IS NULL AND status='active' ORDER BY name");$customers=dbFetchAll("SELECT id,first_name,last_name,status FROM customers WHERE agency_id=:agency AND archived_at IS NULL AND status NOT IN ('blocked','archived') ORDER BY last_name,first_name",['agency'=>$agencyId]);$vehicles=dbFetchAll("SELECT v.id,v.registration_number,v.brand,v.model,v.status,v.base_daily_price,vc.name category_name FROM vehicles v JOIN vehicle_categories vc ON vc.id=v.category_id WHERE v.agency_id=:agency AND v.archived_at IS NULL AND v.status NOT IN ('maintenance','damaged','blocked','sold','retired') ORDER BY v.registration_number",['agency'=>$agencyId]);$selectedCustomer=(int)($_GET['customer_id']??$_POST['customer_id']??0);
backofficeHeader(t('page.reservation_create.title'),'reservation_form.php');pageHeader('page.reservation_create.title','page.reservation_create.description',['breadcrumbs'=>[['label'=>'nav.reservations','href'=>'reservations.php'],['label'=>'page.reservation_create.title']],'secondary'=>['label'=>'common.cancel','href'=>'reservations.php?agency_id='.$agencyId]]);?>
<section class="card form-card"><form method="post"><?=csrfField()?><input type="hidden" name="agency_id" value="<?=e($agencyId)?>"><fieldset><legend><?=e(t('section.rental_context'))?></legend><div class="grid"><label><?=e(t('field.customer'))?><select name="customer_id" required><?php foreach($customers as$c):?><option value="<?=e($c['id'])?>" <?=$selectedCustomer===(int)$c['id']?'selected':''?>><?=e($c['last_name'].' '.$c['first_name'])?></option><?php endforeach;?></select></label><label><?=e(t('field.source'))?><select name="source"><?php foreach(reservationSources()as$v):?><option value="<?=e($v)?>"><?=e(t('option.'.strtolower($v)))?></option><?php endforeach;?></select></label><label><?=e(t('field.initial_status'))?><select name="status"><?php foreach(['quote','pending','confirmed']as$v):?><option value="<?=$v?>" <?=$v==='pending'?'selected':''?>><?=e(translatedStatus($v))?></option><?php endforeach;?></select></label><label><?=e(t('field.return_agency'))?><select name="return_agency_id"><?php foreach($agencies as$a):if(currentUserRole()!==ROLE_OWNER&&!in_array((int)$a['id'],$agencyIds,true))continue;?><option value="<?=e($a['id'])?>" <?=$agencyId===(int)$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></label></div></fieldset>
<fieldset><legend><?=e(t('section.period_allocation'))?></legend><div class="grid"><label><?=e(t('field.pickup_date_time'))?><input type="datetime-local" name="pickup_at" value="<?=e($_POST['pickup_at']??'')?>" required></label><label><?=e(t('field.return_date_time'))?><input type="datetime-local" name="return_at" value="<?=e($_POST['return_at']??'')?>" required></label><label><?=e(t('field.vehicle'))?><select name="vehicle_id" required><?php foreach($vehicles as$v):?><option value="<?=e($v['id'])?>"><?=e($v['registration_number'].' — '.$v['brand'].' '.$v['model'].' — '.$v['category_name'].' — '.money($v['base_daily_price']))?></option><?php endforeach;?></select></label><label><?=e(t('field.pickup_location'))?><input name="pickup_location" value="<?=e($_POST['pickup_location']??'')?>"></label><label><?=e(t('field.return_location'))?><input name="return_location" value="<?=e($_POST['return_location']??'')?>"></label><label><?=e(t('field.delivery_location'))?><input name="delivery_location" value="<?=e($_POST['delivery_location']??'')?>"></label></div><p class="help"><?=e(t('message.availability_rechecked'))?></p></fieldset>
<fieldset><legend><?=e(t('section.commercial_terms'))?></legend><div class="grid"><label><?=e(t('field.options_total'))?><input name="options_total" value="<?=e($_POST['options_total']??'0.00')?>" type="number" step="0.01" inputmode="decimal"></label><label><?=e(t('field.other_fees'))?><input name="fees_total" value="<?=e($_POST['fees_total']??'0.00')?>" type="number" step="0.01" inputmode="decimal"></label><label><?=e(t('field.discount_percent'))?><input name="discount_percent" value="<?=e($_POST['discount_percent']??'0.00')?>" type="number" step="0.01" inputmode="decimal"></label><label><?=e(t('field.tax_percent'))?><input name="tax_rate" value="<?=e($_POST['tax_rate']??'0.00')?>" type="number" step="0.01" inputmode="decimal"></label><label><?=e(t('field.deposit'))?><input name="deposit_amount" value="<?=e($_POST['deposit_amount']??'0.00')?>" type="number" step="0.01" inputmode="decimal"></label><label><?=e(t('field.discount_reason'))?><input name="discount_reason" value="<?=e($_POST['discount_reason']??'')?>"></label><label class="full"><?=e(t('field.internal_notes'))?><textarea name="internal_notes"><?=e($_POST['internal_notes']??'')?></textarea></label></div></fieldset><div class="form-actions"><button class="btn primary"><?=e(t('action.create_reservation'))?></button><a class="btn secondary" href="reservations.php?agency_id=<?=e($agencyId)?>"><?=e(t('common.cancel'))?></a></div></form></section><?php backofficeFooter();
